contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test: send amount to c.go and assert owner invariant
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // allow any amount but ensure this contract has the funds to send
        require(address(this).balance >= amount);

        // observe owner before
        address beforeOwner = c.owner(); if (__ESBMC_reverted()) return;

        // call C.go with the supplied amount, catching revert
        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe owner after
        address afterOwner = c.owner(); if (__ESBMC_reverted()) return;

        // General rule: owner never changes by calling go
        assert(afterOwner == beforeOwner);
    }

    // allow receiving Ether if forwarded to this test contract
    receive() external payable {}
}

